import { describe, it } from "vitest";

// Reading: all premiums below are for a customer with 0 years and a first quote unless stated,
// so every premium includes the 10 % first insurance surcharge and the 5 G fee.
// Reading: every rejection makes the scenario run throw an Error (the CLI maps it to exit code 1 + stderr).

describe("quote: base premiums", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("sword (base 100 G) -> premium 115 G");
  it.todo("amulet (base 60 G) -> premium 71 G");
  it.todo("staff (base 80 G) -> premium 93 G");
  it.todo("potion (base 40 G) -> premium 49 G");
  it.todo("single rune (base 25 G) -> premium 33 G (32.5 rounded up)");
  it.todo("single moonstone (base 25 G) -> premium 33 G (32.5 rounded up)");
  it.todo("unknown item type (broomstick) -> run is rejected with an error");
});

describe("quote: building block of 3 alike components", () => {
  it.todo("2 runes -> base 50 G -> premium 60 G");
  it.todo("3 runes -> base 60 G (block applies) -> premium 71 G");
  it.todo("3 moonstones -> base 60 G (block applies) -> premium 71 G");
  it.todo("4 runes -> base 100 G (no block, block requires exactly 3) -> premium 115 G");
  it.todo("7 runes -> base 175 G -> premium 198 G (197.5 rounded up in the MHPCO's favor)");
  it.todo("2 runes + 1 moonstone -> base 75 G (different types, no block) -> premium 88 G");
  it.todo("3 runes + 3 moonstones -> base 120 G (two separate blocks) -> premium 137 G");
});

describe("quote: premium modifiers", () => {
  it.todo("cursed steel sword, enchantment 3 -> 100 + 50 + 10 + 5 = 165 G");
  it.todo("sword with enchantment 5 -> high enchantment surcharge applies -> 145 G");
  it.todo("cursed sword with enchantment 5 -> both surcharges apply -> 195 G");
  it.todo("sword with enchantment 4 -> no high enchantment surcharge -> 115 G");
  it.todo("cursed sword with enchantment 4 -> only curse surcharge -> 165 G");
  it.todo("cursed sword + plain amulet -> curse surcharge applies to the sword only -> 231 G");
  it.todo("customer with exactly 2 years -> loyalty discount applies -> sword 95 G");
  it.todo("customer with 1 year -> no loyalty discount -> sword 115 G");
  it.todo("loyalty discount applies to the policy base premium -> 2 years, cursed sword + amulet -> 199 G");
  it.todo("second quote in the scenario receives the 15 % follow-up discount -> sword 115 G then 100 G");
  it.todo("integration: 3 years, second quote, cursed sword with enchantment 7 -> 160 G");
});

describe("claim: reimbursement", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G, remaining cap 1600 G");
  it.todo("rune, damage 200 G -> payout 100 G, remaining cap 400 G");
  it.todo("damage smaller than the deductible -> payout 0 G (reading: payout never negative)");
  it.todo("sword with enchantment 7, damage 1000 G -> payout 900 G (below the 50 % threshold)");
  it.todo("dragon sword, enchantment 8, damage 1000 G -> payout 400 G (50 % clause, then deductible)");
  it.todo("dragon sword, enchantment 9, damage 1000 G -> payout 400 G (50 % clause wins)");
  it.todo("dragon sword, enchantment 5, damage 800 G -> payout 700 G (dragon clause only)");
  it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % clause only)");
  it.todo("payout of 350.5 G (steel sword, enchantment 8, damage 901 G) -> 350 G (rounded down)");
  it.todo("sword 500 G + amulet 300 G damaged by a dragon attack -> payout 600 G (deductible per damaged item)");
  it.todo("two damages with different items of the same type are matched in policy order");
});

describe("claim: insurance sum and cap", () => {
  it.todo("amulet (insured 600 G) -> cap 1200 G: damage 300 G -> payout 200 G, remaining cap 1000 G");
  it.todo("staff (insured 800 G) -> cap 1600 G: damage 300 G -> payout 200 G, remaining cap 1400 G");
  it.todo("potion (insured 400 G) -> cap 800 G: damage 300 G -> payout 200 G, remaining cap 600 G");
  it.todo("moonstone (insured 250 G) -> cap 500 G: damage 200 G -> payout 100 G, remaining cap 400 G");
  it.todo("sword + amulet -> insurance sum 1600 G, cap 3200 G: sword 500 G + amulet 300 G -> remaining cap 2600 G");
  it.todo("cursed sword -> cap stays 2000 G (premium modifiers do not raise the cap)");
  it.todo("sword + 3 runes -> insurance sum 1750 G, cap 3500 G (block does not change the sum)");
  it.todo("two swords -> insurance sum 2000 G, cap 4000 G: both swords damaged by 500 G -> payout 800 G, remaining cap 3200 G");
  it.todo("two successive claims of 1500 G on a sword -> 1400 G / remaining 600 G, then 600 G / remaining 0 G");
  it.todo("claims refer to the policy by quote step index and keep separate caps");
});

describe("claim: rejections", () => {
  it.todo("two sword damages but only one sword insured -> whole claim rejected with an error");
  it.todo("amulet damaged although only a sword is insured -> rejected with an error");
  it.todo("damage with unknown item type -> rejected with an error");
  it.todo("damage with amount -200 -> rejected with an error");
});

