export type Item = { type: string };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: { op: "quote"; items: Item[] }[];
};

export type StepResult = { premium: number };

const PROCESSING_FEE = 5;
const PERCENT = 100;
const FIRST_INSURANCE_PERCENT = 10;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

function basePremiumOf(item: Item): number {
  if (!Object.hasOwn(BASE_PREMIUMS, item.type)) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return BASE_PREMIUMS[item.type];
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return {
    results: scenario.steps.map((step) => {
      const base = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
      const surcharge = (base * FIRST_INSURANCE_PERCENT) / PERCENT;
      return { premium: Math.ceil(base + surcharge) + PROCESSING_FEE };
    }),
  };
}

