=== src/claim-office.ts
import { type Damage, type Policy, fileClaim, openPolicy } from "./claim.js";
import type { Item } from "./price-list.js";
import { quotePremium } from "./quote.js";

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const { yearsWithMHPCO } = scenario.customer;
  const policies = new Map<number, Policy>();
  return {
    results: scenario.steps.map((step, index) => {
      if (step.op === "quote") {
        policies.set(index, openPolicy(step.items));
        return { premium: quotePremium(step.items, { yearsWithMHPCO, isFollowUpContract: index > 0 }) };
      }
      const policy = policies.get(step.policy) as Policy;
      return fileClaim(policy, step.incident.damages);
    }),
  };
}
=== src/claim.ts
import { type Item, insuranceSumOf } from "./price-list.js";

export type Damage = { itemType: string; amount: number };

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;
const PERCENT = 100;
const HIGH_ENCHANTMENT_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;

function reimbursedAmount(item: Item, damage: Damage): number {
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
    return (damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT) / PERCENT;
  }
  return damage.amount;
}

function payoutForDamage(item: Item, damage: Damage): number {
  return Math.max(reimbursedAmount(item, damage) - DEDUCTIBLE, 0);
}

type DamagedItem = { item: Item; damage: Damage };

function assertValidDamage(damage: Damage): void {
  if (damage.amount < 0) {
    throw new Error(`Damage amount must not be negative: ${damage.amount}`);
  }
}

function takeCoveringItem(unclaimed: Item[], damage: Damage): Item {
  const index = unclaimed.findIndex((candidate) => candidate.type === damage.itemType);
  if (index === -1) {
    throw new Error(`Damage to ${damage.itemType} is not covered by the policy`);
  }
  return unclaimed.splice(index, 1)[0];
}

function matchDamagesToItems(items: Item[], damages: Damage[]): DamagedItem[] {
  const unclaimed = [...items];
  return damages.map((damage) => {
    assertValidDamage(damage);
    return { item: takeCoveringItem(unclaimed, damage), damage };
  });
}

function damagesPayout(items: Item[], damages: Damage[]): number {
  const total = matchDamagesToItems(items, damages).reduce(
    (sum, { item, damage }) => sum + payoutForDamage(item, damage),
    0,
  );
  return Math.floor(total);
}

export type Policy = { items: Item[]; remainingCap: number };

export function openPolicy(items: Item[]): Policy {
  return { items, remainingCap: insuranceSumOf(items) * CAP_MULTIPLIER };
}

export function fileClaim(policy: Policy, damages: Damage[]): { payout: number; remainingCap: number } {
  const payout = Math.min(damagesPayout(policy.items, damages), policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
=== src/quote.ts
import { type Item, basePremiumOf, itemsBasePremium } from "./price-list.js";

const PROCESSING_FEE = 5;
const PERCENT = 100;
const FIRST_INSURANCE_PERCENT = 10;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;
const CURSED_PERCENT = 50;
const HIGH_ENCHANTMENT_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;

function riskSurchargePercent(item: Item): number {
  const cursed = item.cursed ? CURSED_PERCENT : 0;
  const highlyEnchanted = (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_PERCENT : 0;
  return cursed + highlyEnchanted;
}

export type QuoteCustomer = { yearsWithMHPCO: number; isFollowUpContract: boolean };

function loyaltyDiscountPercent(yearsWithMHPCO: number): number {
  return yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT_PERCENT : 0;
}

function followUpDiscountPercent(isFollowUpContract: boolean): number {
  return isFollowUpContract ? FOLLOW_UP_DISCOUNT_PERCENT : 0;
}

function policyPercent(customer: QuoteCustomer): number {
  return (
    FIRST_INSURANCE_PERCENT -
    loyaltyDiscountPercent(customer.yearsWithMHPCO) -
    followUpDiscountPercent(customer.isFollowUpContract)
  );
}

export function quotePremium(items: Item[], customer: QuoteCustomer): number {
  const base = itemsBasePremium(items);
  const riskSurcharge = items.reduce(
    (sum, item) => sum + (basePremiumOf(item) * riskSurchargePercent(item)) / PERCENT,
    0,
  );
  const policyAdjustment = (base * policyPercent(customer)) / PERCENT;
  return Math.ceil(base + riskSurcharge + policyAdjustment) + PROCESSING_FEE;
}
=== src/price-list.ts
export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
type PriceListEntry = { insuranceValue: number; basePremium: number };

const PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
  rune: { insuranceValue: 250, basePremium: 25 },
  moonstone: { insuranceValue: 250, basePremium: 25 },
};

function priceListEntryOf(item: Item): PriceListEntry {
  if (!Object.hasOwn(PRICE_LIST, item.type)) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return PRICE_LIST[item.type];
}

export function insuranceValueOf(item: Item): number {
  return priceListEntryOf(item).insuranceValue;
}

export function insuranceSumOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
}

export function basePremiumOf(item: Item): number {
  return priceListEntryOf(item).basePremium;
}

export function itemsBasePremium(items: Item[]): number {
  const countOf = (type: string) => items.filter((item) => item.type === type).length;
  const blockTypes = COMPONENT_TYPES.filter((type) => countOf(type) === COMPONENT_BLOCK_SIZE);
  const separateItems = items.filter((item) => !blockTypes.includes(item.type));
  return (
    blockTypes.length * COMPONENT_BLOCK_PREMIUM +
    separateItems.reduce((sum, item) => sum + basePremiumOf(item), 0)
  );
}

